 if exists(select 1 from pg_roles where rolname in ('authenticated','anon') and (rolsuper or rolbypassrls)) or exists(select 1 from pg_class where oid in ('public.content_reviews'::regclass,'public.content_versions'::regclass,'public.growth_opportunities'::regclass,'public.audit_events'::regclass) and not relrowsecurity) then raise exception 'Auth role or RLS drift'; end if;
 if (select count(*) from supabase_migrations.schema_migrations)<>23 then raise exception 'Expected historical baseline 23; reconcile drift before installation'; end if;
 if to_regprocedure('public.review_url_result(uuid,uuid,uuid,text,text,text,jsonb)') is not null or to_regprocedure('private.review_url_result_impl(uuid,uuid,uuid,text,text,text,jsonb)') is not null or exists(select 1 from information_schema.columns where table_schema='public' and table_name='content_reviews' and column_name like 'url_review_%') or exists(select 1 from pg_constraint where conrelid='public.content_reviews'::regclass and conname in ('content_reviews_url_request_unique','content_reviews_url_shape')) then raise exception 'Review already installed or partial schema; reconcile, never replay install'; end if;
