 if exists(select 1 from (values('authenticated'),('anon')) r(name) cross join (values('public.content_reviews'),('public.content_versions'),('public.growth_opportunities')) t(name) where has_table_privilege(r.name,t.name,'INSERT,UPDATE,DELETE,TRUNCATE')) then raise exception 'Unexpected direct table write'; end if;
